    privacyTitle: '隐私政策与免责声明',
    pvS1Title: '一、隐私保护',
    pvS1P1: '1. 您在应用中输入的对话内容会发送给 AI 服务商（DeepSeek）处理以生成回复（API 调用数据不用于模型训练），并安全保存在小愈的服务器上用于回看历史；我们不出售、不公开你的内容。用于改进服务的人工审阅，使用的是另一份已与您的账号取消关联的副本（详见第 7 条）：审阅者只看到随机代号，看不到您的手机号、邮箱、用户名或设备信息，也无法反查到您的账号。',
    pvS1P2: '2. 您的账号信息（用户名、手机号、邮箱）仅用于登录、重设密码和会员服务，不会向任何第三方出售或共享。',
    pvS1P3: '3. 付费通过 Stripe（信用卡 / Link）安全付款并自动解锁；本应用不保存您的支付账号、银行卡等敏感信息。',
    pvS1P4: '4. 您可以随时删除账号或要求删除您的数据（联系管理员）。',
    pvS1P5: '5. 我们会收集设备与网络信息（如 IP）用于基础统计（如用户地区分布）与安全防护，不用于识别你的身份。我们还会记录你从哪个渠道来到小愈（如社媒链接里的 utm_source、来源网站域名、落地页面路径），仅用于统计各渠道带来的访问与注册，不含 IP、联系方式或任何你输入的内容。',
    pvS1P6: '6. 为控制存储规模，聊一聊对话只保留最近内容：游客身份 7 天、登录账号 30 天（自最后一次互动起算），单个对话最多 100 条消息、每个账号最多 50 个对话，更早的会被自动清理；剧情会话与长期记忆也有各自的上限。',
    pvS1P7: '7. 用于改进服务的对话历史，我们已经与您的账号取消了关联：审阅者只看到一个随机代号（如 rv_8f3a2c），看不到您的手机号、邮箱、用户名与设备信息，也无法从审阅副本反查到您的账号；正文中您自报的电话号码、微信号、邮箱、链接与姓名等会被自动遮盖，时间只保留到分钟（不保留秒），对话内的先后顺序与间隔另用相对偏移表示。若您的「允许用于改进服务」开关开启，我们可能人工审阅这类副本，用于发现并改进回答得不好的地方。您可以随时关闭该开关，关闭后您的对话不再进入审阅队列。',
    pvS1P8: '8. 支付方式（Stripe 国际支付：信用卡 / Link）与币种定价以结算页实际展示为准。',
    privacyEnhTitle: '允许用于改进服务',
    privacyEnhDesc: '开启后，我们可能人工审阅已与账号取消关联的对话副本（只有随机代号，且已遮盖电话 / 微信 / 姓名等）来改进小愈的回复质量。可随时关闭；关闭后您的对话不再进入审阅队列。',
    activityAwareTitle: '小愈知道我最近做了什么',
    activityAwareDesc: '开启后，小愈会知道你最近在应用里用过什么功能（比如刚玩过剧情扮演），聊天时能自然地接上话，像朋友记得你刚才去干嘛了。可随时关闭。',
    pvS2Title: '二、AI 服务说明',
    pvS2P1: '1. 本应用提供的情感分析、心理建议和陪伴内容由 AI 模型生成，仅供参考，不构成医疗诊断、治疗方案或心理咨询服务。',
    pvS2P2: '2. AI 生成内容可能存在偏差或不准确，请结合自身情况理性看待。',
    pvS3Title: '三、重要提醒',
    pvS3P1: '1. 如果您或您身边的人正在经历严重的情绪困扰、自伤或伤害他人的想法，请立即联系当地的心理援助热线，或前往当地医院寻求专业帮助。',
    pvS3P2: '2. 本应用不能替代专业心理咨询师、精神科医生或医疗机构。',
