    renewalTip: '（續費可疊加時長）',
    privacyTitle: '隱私政策與免責聲明',
    pvS1Title: '一、隱私保護',
    pvS1P1: '1. 您在應用程式中輸入的對話內容會發送給 AI 服務商（DeepSeek）處理以生成回覆（API 呼叫資料不用於模型訓練），並安全保存在小愈的伺服器上用於回看歷史；我們不出售、不公開你的內容。用於改進服務的人工審閱，使用的是另一份已與您的帳號取消關聯的副本（詳見第 7 條）：審閱者只看到隨機代號，看不到您的手機號、電子郵件、使用者名稱與裝置資訊，也無法反查到您的帳號。',
    pvS1P2: '2. 您的帳號資訊（用戶名、手機號、信箱）僅用於登入、重設密碼和會員服務，不會向任何第三方出售或共享。',
    pvS1P3: '3. 付費透過 Stripe（信用卡 / Link）安全付款並自動解鎖；本應用不保存您的支付帳號、銀行卡等敏感資訊。',
    pvS1P4: '4. 您可以隨時刪除帳號或要求刪除您的資料（聯絡管理員）。',
    pvS1P5: '5. 我們會收集裝置與網路資訊（如 IP）用於基礎統計（如用戶地區分布）與安全防護，不用於識別你的身分。我們亦會記錄你從哪個渠道來到小愈（如社群連結裡的 utm_source、來源網站網域、落地頁面路徑），僅用於統計各渠道帶來的造訪與註冊，不含 IP、聯絡方式或任何你輸入的內容。',
    pvS1P6: '6. 為控制儲存規模，聊一聊對話只保留最近內容：訪客身分 7 天、登入帳號 30 天（自最後一次互動起算），單一對話最多 100 則訊息、每個帳號最多 50 個對話，更早的會自動清理；劇情會話與長期記憶也有各自的上限。',
    pvS1P7: '7. 用於改進服務的對話歷史，我們已經與您的帳號取消了關聯：審閱者只看到一個隨機代號（如 rv_8f3a2c），看不到您的手機號、電子郵件、使用者名稱與裝置資訊，也無法從審閱副本反查到您的帳號；正文中您自報的電話號碼、微信號、電子郵件、連結與姓名等會被自動遮蓋，時間只保留到分鐘（不保留秒），對話內的先後順序與間隔另用相對偏移表示。若您的「允許用於改進服務」開關開啟，我們可能人工審閱這類副本，用於發現並改進回答得不好的地方。您可以隨時關閉該開關，關閉後您的對話不再進入審閱佇列。',
    pvS1P8: '8. 付款方式（Stripe 國際支付：信用卡 / Link）與幣別定價以結算頁實際顯示為準。',
    privacyEnhTitle: '允許用於改進服務',
    privacyEnhDesc: '開啟後，我們可能人工審閱已與帳號取消關聯的對話副本（只有隨機代號，且已遮蓋電話 / 微信 / 姓名等）來改進小愈的回覆品質。可隨時關閉；關閉後您的對話不再進入審閱佇列。',
    activityAwareTitle: '小愈知道我最近做了什麼',
    activityAwareDesc: '開啟後，小愈會知道你最近在應用裡用過什麼功能（例如剛玩過劇情扮演），聊天時能自然地接上話，像朋友記得你剛才去幹嘛了。可隨時關閉。',
    pvS2Title: '二、AI 服務說明',
    pvS2P1: '1. 本應用提供的情感分析、心理建議和陪伴內容由 AI 模型生成，僅供參考，不構成醫療診斷、治療方案或心理諮詢服務。',
    pvS2P2: '2. AI 生成內容可能存在偏差或不準確，請結合自身情況理性看待。',
    pvS3Title: '三、重要提醒',
    pvS3P1: '1. 如果您或您身邊的人正在經歷嚴重的情緒困擾、自傷或傷害他人的想法，請立即聯絡當地的心理援助熱線，或前往當地醫院尋求專業幫助。',
    pvS3P2: '2. 本應用不能替代專業心理諮詢師、精神科醫生或醫療機構。',
    pvS3P3: '3. 使用本應用即表示您已閱讀並同意以上條款。',
