    rpStyleSection: 'Narration style',
    rpStyleSectionHint: 'How the story is written: length, register and pace. Person and content limits are identical in both — you are always "you", the AI character is third-person. Takes effect immediately and syncs with your account.',
    rpStyleClassicDetail: 'Length: 400–700 Chinese characters (same band in intimate scenes). Register: literary long sentences, detail chained together, cinematic framing; dialogue never carries the whole reply. Pace: every turn ends on a hook (an action awaiting you, a suspense beat, or a line left unfinished). Best when you want to read a story.',
    rpStyleImmersiveDetail: 'Length: one or two lines, under 100 characters in everyday talk; expands to 250–450 when you push forward or the scene turns intimate. Register: colloquial, dialogue-led, action and expression in brackets; intimate scenes switch to body action and sensory detail. Pace: it answers what you just wrote and never opens a new topic on its own. Best for a chat-like session.',
