    // —— Story Mode module intro: module-level copy covering the three parallel modes ——
    // Mode names are not hard-coded here: the page reads the same tab keys (roleplayTitle / wyTabLabel /
    // wwT('tab')) the switcher uses, so naming can never drift between the two places.
    rpIntroSub: 'One entrance, three modes: AI Roleplay · AI Story · AI Werewolf',
    rpIntroWhatTitle: 'What is this',
    rpIntroWhatBody: 'This is not one game but three, side by side — all generated live by AI, and the story bends to your choices:',
    rpIntroModeRoleplayBody: 'Pick a story, step in as yourself, and interact freely with the AI characters.',
    rpIntroModeWenyouBody: 'One choice per turn, all the way to an ending that is only yours.',
    rpIntroModeWerewolfBody: 'Sit down with the characters you raised and play a round — solo works too.',
    rpIntroSourceTitle: 'Story source',
    rpIntroSourceBody: 'Roleplay stories include original AI works and storylines by online creators — each creator is credited below their story, and more will be added over time. Story games include built-in premises and ones you generate yourself. Werewolf is a rules-based game and needs no script. All for interactive play only.',
    rpIntroPriceTitle: 'Pricing',
    rpIntroPriceBody: 'No charge per story — browsing stories and settings is free. All three modes are generated live by AI and billed by usage, sharing the same quota as Chat (Werewolf is billed per game; AI story generation is Pro-only).',
    rpIntroRiskTitle: 'Heads-up',
    rpIntroRiskBody: 'Fictional stories, nothing to do with reality. Stay grounded, take care, do not imitate anything.',
    rpIntroStart: 'Pick a mode and start',
    rpIntroAgain: 'About this feature',
    // —— About Xiaoyu ——
    aboutTitle: 'About Xiaoyu',
    aboutSub: 'Everything about Xiaoyu, in one place',
    faq: 'FAQ',
    aboutFeatureTitle: 'Three ways to be with you',
    aboutBrandTitle: 'What is Xiaoyu',
    aboutBrandBody: 'Every feeling deserves to be understood. Xiaoyu (sh-yao-yu) is a glowing little sprout who means "gentle healing" — she holds you when you are low and cheers with you when you are bright.',
    aboutStoryTitle: 'Her story',
    aboutStoryBody: 'Xiaoyu is a little sprout from a small city in the East, who set out to hug the whole world. The bud on her head is her heart — it glows when someone is gentle with her. She holds a jar of soft light, to share with anyone who is hurting. And she wants the world to light her up too.',
    aboutStoryNickname: 'Her nickname is Yu — it sounds just like "you". Because when you talk to her, she\'s listening to you.',

    aboutRoleplayTitle: 'Roleplay',
    aboutRoleplayDesc: 'Step into different stories and live another life. AI plays the characters; each story has its own cast and storyline.',
