    renewalBtn: 'Tap to renew',
    renewalTip: ' (renewal extends your time)',
    privacyTitle: 'Privacy Policy & Disclaimer',
    pvS1Title: '1. Privacy',
    pvS1P1: '1. The conversations you enter are sent to our AI provider (DeepSeek) to generate replies (API data is not used for model training) and stored securely on Xiaoyu\'s server for you to revisit; we never sell or publish your content. Human review for improving the service uses a separate copy that is no longer linked to your account (see item 7): reviewers see only a random code — never your phone number, email, username or device information — and that copy cannot be traced back to your account.',
    pvS1P2: '2. Your account info (username, phone, email) is used only for login, password reset and membership; never sold or shared with third parties.',
    pvS1P3: '3. Payments go through Stripe (credit card or Link) securely with instant unlock; we never store your payment accounts or bank cards.',
    pvS1P4: '4. You can delete your account or request data deletion at any time (contact the admin).',
    pvS1P5: '5. We collect device and network information (such as IP) for basic statistics (e.g., user region distribution) and security; it is not used to identify you personally. We also record which channel brought you here (for example a utm_source in a social link, the referring site domain, or the landing page path) — used only to count visits and sign-ups per channel, and containing no IP address, no contact details and nothing you type.',
    pvS1P6: '6. To keep storage in check, chat conversations are kept for a limited window — 7 days for guest use and 30 days for a signed-in account, counted from your last interaction — with the latest 100 messages per chat and the latest 50 chats per account retained; older ones are automatically cleaned up. Roleplay sessions and long-term memory have their own caps.',
    pvS1P7: "7. For conversation history used to improve the service, we have already removed the link to your account: reviewers see only a random code (e.g. rv_8f3a2c) — never your phone number, email, username or device information — and the review copy cannot be traced back to your account. Phone numbers, WeChat IDs, emails, links and names you mention in the text are masked automatically, and timestamps are kept only to the minute (no seconds) — the order and spacing inside a conversation are shown as relative offsets instead. If your \"Allow use to improve the service\" toggle is on, we may have humans review such copies in order to find and fix cases where a reply falls short. You can turn this off anytime — once it is off, your conversations no longer enter the review queue.",
    pvS1P8: "8. Payment method (Stripe international payment: credit card / Link) and currency pricing are shown as displayed on the checkout page.",
    privacyEnhTitle: 'Allow use to improve the service',
