const LANG_KEY = 'cure_lang';

// 内存兜底默认语言（不写 localStorage）：main.tsx 首访按浏览器语言设一个合理默认，
// 使首绘就能用对语言，同时保留「首访仍可再按 IP 校准」的语义（geo 覆盖后 setLang 才持久化）。
let fallbackLang: Lang = 'zh-TW';
export function setDefaultLang(l: Lang): void { fallbackLang = l; }

export function getLang(): Lang {
  try {
    const v = localStorage.getItem(LANG_KEY);
    if (v === 'zh-CN' || v === 'zh-TW' || v === 'en') return v;
  } catch { /* 忽略 */ }
  return fallbackLang; // 默认（未手动选过语言的新用户/游客；main.tsx 可按浏览器设为更贴近的默认）
}

export function setLang(l: Lang): void {
  try { localStorage.setItem(LANG_KEY, l); } catch { /* 忽略 */ }
  // 同时写一份 cookie（与皮肤 cure_skin 同一套做法）：localStorage 不可用（隐私模式/存储受限）时，
  // index.html 的首帧内联脚本仍能读到语言，避免"先按浏览器语言出、再切到你选的语言"那一闪。
  try { document.cookie = `${LANG_KEY}=${encodeURIComponent(l)}; path=/; max-age=31536000; SameSite=Lax`; } catch { /* 忽略 */ }
}

/** 返回已保存的界面语言（未设置返回 null） */
export function getStoredLang(): Lang | null {
  try {
    const v = localStorage.getItem(LANG_KEY);
    if (v === 'zh-CN' || v === 'zh-TW' || v === 'en') return v;
  } catch { /* 忽略 */ }
  return null;
}

/** 每语言对外 meta 描述（SEO；红线：陪伴非治疗、gentle healing 口径） */
const SEO_DESC: Record<Lang, string> = {
  'zh-CN': '小愈是一款 AI 情感陪伴应用：接住你的低落，也见证你的快乐。无需下载，浏览器即开即用。温柔疗愈，陪伴而非治疗。',
  'zh-TW': '小愈是一款 AI 情感陪伴應用：接住你的低落，也見證你的快樂。無需下載，瀏覽器即開即用。溫柔療癒，陪伴而非治療。',
  en: 'Xiaoyu is an AI emotional companion that listens to every feeling — from the hard moments to the bright ones. Free to start in your browser, no download. Gentle healing, not a substitute for therapy.',
};

/** 让浏览器标签页标题、html lang 与对外 meta（description/OG）跟随当前语言 */
export function applyDocumentTitle(): void {
  try {
    const lang = getLang();
    const brand = lang === 'en' ? 'Xiaoyu' : '小愈';
    // SEO 关键词前置（品牌 + 目标词），提高如「AI companion / AI 情感陪伴」类查询的匹配度
    const TITLE_KEYWORD: Record<Lang, string> = {
      'zh-CN': 'AI 情感陪伴',
      'zh-TW': 'AI 情感陪伴',
      en: 'Free AI Companion for Emotional Support',
    };
    const title = brand + ' — ' + (TITLE_KEYWORD[lang] ?? '');
    document.title = title;
    document.documentElement.lang = lang;
    // 语言已真正应用 → 摘掉首屏脚本打上的「语言不一致」标记（index.html 里的 style 靠它隐藏预渲染内容）。
    // 放在这里而不是 main.tsx：applyDocumentTitle() 是"语言落地"的唯一出口，标记也该只有一个出口。
    document.documentElement.removeAttribute('data-lang-swap');
    const desc = SEO_DESC[lang] ?? SEO_DESC['zh-CN'];
    const setMeta = (attr: 'name' | 'property', key: string, content: string) => {
      let el = document.head.querySelector<HTMLMetaElement>(`meta[${attr}="${key}"]`);
      if (!el) {
        el = document.createElement('meta');
        el.setAttribute(attr, key);
        document.head.appendChild(el);
      }
      el.setAttribute('content', content);
    };
    setMeta('name', 'description', desc);
    setMeta('property', 'og:description', desc);
    setMeta('property', 'og:title', title);
  } catch { /* 忽略 */ }
}

export function t(key: string, vars?: Record<string, string | number>): string {
  let s = DICT[getLang()][key] ?? DICT['zh-CN'][key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      /**
       * ⚠️ 必须替换**全部**出现，不能只替第一处：`String.replace('{n}', v)` 只换第一个，
       * 于是「朋友注册得 {n} 次；他开始聊天后你得 {n} 次」这种**同值出现两次**的文案
       * 会把第二个 `{n}` 原样漏到界面上（2026-09-21 真机走查在「我的」面板看到过；
       * 全库共 4 个键 × 3 语受影响：profileInviteDesc / inviteEarnHint / inviteRecordsTooNew / quotaShareDesc）。
       * 用 split/join 代替 replace，顺带避开正则里的 `$&` 之类的替换语义坑。
       */
      s = s.split(`{${k}}`).join(String(v));
    }
  }
  return s;
}


